import{_ as r,g as a,e as t,a4 as n}from"./chunks/framework.CEYJDsBW.js";const f=JSON.parse('{"title":"Client-Server Networking","description":"","frontmatter":{},"headers":[],"relativePath":"en/anvilcraft/21.1/network/index.md","filePath":"en/anvilcraft/21.1/network/index.md"}'),i={name:"en/anvilcraft/21.1/network/index.md"};function o(s,e,l,d,c,p){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="client-server-networking" tabindex="-1">Client-Server Networking <a class="header-anchor" href="#client-server-networking" aria-label="Permalink to &quot;Client-Server Networking&quot;">​</a></h1><p>When a screen needs server data, check first whether AnvilCraft already defines a packet for that operation. Redstone wire signal queries and box scroll selections already have built-in protocols. World simulation for power grids and pipe networks is covered separately in <a href="./../power/">Power Grid &amp; Wattage</a> and <a href="./../fluid/">Pipes &amp; Fluids</a>.</p><ul><li><a href="./wire.html">Requesting and Displaying Wire Readouts</a> explains the requester, responder, range, and caching.</li><li><a href="./selection.html">Syncing Menu Selections</a> covers slot indexes and index semantics for pill boxes and amulet boxes.</li><li><a href="./registration.html">Registering Your Own Payloads</a> demonstrates registering server queries under your own namespace.</li><li><a href="./split.html">Chunked Transfer for Large Data</a> covers codecs, chunk sizes, threading, and delivery timing.</li></ul><p>In <code>RegisterPayloadHandlersEvent</code> on the mod event bus, AnvilCraft creates a <code>PayloadRegistrar</code> with protocol version <code>&quot;2&quot;</code> and calls <code>NetworkRegistrar.register(registrar, AnvilCraft.MOD_ID)</code>. Dependents sending built-in packets use the packet types directly; registering the same IDs yourself conflicts with the original registration. <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/AnvilCraft.java" target="_blank" rel="noreferrer">Built-in protocol registration</a></p>',4)])])}const g=r(i,[["render",o]]);export{f as __pageData,g as default};
